 17	    public static ValidationError validateCheckoutRequest(CheckoutRequest req) throws SQLException {
 18	        if (req.items == null || req.items.isEmpty()) {
 19	            return new ValidationError("INVALID_ORDER", 422);
 20	        }
 21	
 22	        if (req.customer == null || req.customer.cpf == null || req.customer.cpf.isEmpty() ||
 23	            req.customer.email == null || req.customer.email.isEmpty()) {
 24	            return new ValidationError("INVALID_ORDER", 422);
 25	        }
 26	
 27	        Set<String> seenSkus = new HashSet<>();
 28	        for (CheckoutRequest.OrderItemData item : req.items) {
 29	            if (item.sku == null || item.sku.isEmpty() || item.quantity <= 0) {
 30	                return new ValidationError("INVALID_ORDER", 422);
 31	            }
 32	            if (seenSkus.contains(item.sku)) {
 33	                return new ValidationError("INVALID_ORDER", 422);
 34	            }
 35	            seenSkus.add(item.sku);
 36	        }
 37	
 38	        for (CheckoutRequest.OrderItemData item : req.items) {
 39	            Product product = ProductService.getProduct(item.sku);
 40	            if (product == null) {
 41	                return new ValidationError("UNKNOWN_PRODUCT", 422);
 42	            }
 43	            if (product.discontinued) {
 44	                return new ValidationError("PRODUCT_DISCONTINUED", 422);
 45	            }
 46	            if (product.stock < item.quantity) {
 47	                return new ValidationError("INSUFFICIENT_STOCK", 422);
 48	            }
 49	        }
 50	
 51	        if (req.clubTier == null || req.clubTier.isEmpty()) {
 52	            return new ValidationError("INVALID_CLUB_TIER", 422);
 53	        }
 54	        try {
 55	            Enums.ClubTier.valueOf(req.clubTier);
 56	        } catch (IllegalArgumentException e) {
 57	            return new ValidationError("INVALID_CLUB_TIER", 422);
 58	        }
 59	
 60	        if (req.region == null || req.region.isEmpty()) {
 61	            return new ValidationError("INVALID_REGION", 422);
 62	        }
 63	        try {
 64	            Enums.Region.valueOf(req.region);
 65	        } catch (IllegalArgumentException e) {
 66	            return new ValidationError("INVALID_REGION", 422);
 67	        }
 68	
 69	        if (req.zipCode == null || !ZIP_CODE_PATTERN.matcher(req.zipCode).matches()) {
 70	            return new ValidationError("INVALID_ZIP_CODE", 422);
 71	        }
 72	
 73	        if (req.shippingMethod == null || req.shippingMethod.isEmpty()) {
 74	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
 75	        }
 76	        try {
 77	            Enums.ShippingMethod.valueOf(req.shippingMethod);
 78	        } catch (IllegalArgumentException e) {
 79	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
 80	        }
 81	
 82	        ValidationError shippingError = validateShippingMethod(req);
 83	        if (shippingError != null) {
 84	            return shippingError;
 85	        }
 86	
 87	        if (req.paymentMethod == null || req.paymentMethod.isEmpty()) {
 88	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
 89	        }
 90	        try {
 91	            Enums.PaymentMethod.valueOf(req.paymentMethod);
 92	        } catch (IllegalArgumentException e) {
 93	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
 94	        }
 95	
 96	        int installments = req.installments != null ? req.installments : 1;
 97	        if (!isInstallmentsValid(req.paymentMethod, installments)) {
 98	            return new ValidationError("INVALID_INSTALLMENTS", 422);
 99	        }
100	
101	        if (req.coupon != null && !req.coupon.isEmpty() && !isCouponValid(req.coupon)) {
102	            return new ValidationError("INVALID_COUPON", 422);
103	        }
104	
105	        ValidationError couponError = validateCouponApplicability(req);
106	        if (couponError != null) {
107	            return couponError;
108	        }
109	
110	        ValidationError paymentError = validatePaymentMethod(req);
111	        if (paymentError != null) {
112	            return paymentError;
113	        }
114	
115	        return null;
116	    }
