118	    private static ValidationError validateShippingMethod(CheckoutRequest req) throws SQLException {
119	        Enums.ShippingMethod method = Enums.ShippingMethod.valueOf(req.shippingMethod);
120	
121	        if (method == Enums.ShippingMethod.COURIER) {
122	            double totalWeight = 0;
123	            for (CheckoutRequest.OrderItemData item : req.items) {
124	                Product product = ProductService.getProduct(item.sku);
125	                totalWeight += product.weightKg * item.quantity;
126	            }
127	            if (totalWeight > MAX_COURIER_WEIGHT) {
128	                return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
129	            }
130	        }
131	
132	        if (method == Enums.ShippingMethod.ECONOMY || method == Enums.ShippingMethod.EXPRESS) {
133	            String translogUrl = System.getenv("TRANSLOG_URL");
134	            if (translogUrl == null || translogUrl.isEmpty()) {
135	                return null;
136	            }
137	
138	            double totalWeight = 0;
139	            for (CheckoutRequest.OrderItemData item : req.items) {
140	                Product product = ProductService.getProduct(item.sku);
141	                totalWeight += product.weightKg * item.quantity;
142	            }
143	
144	            String service = method == Enums.ShippingMethod.ECONOMY ? "STD" : "EXP";
145	            int weightGrams = (int) (totalWeight * 1000);
146	
147	            TranslogResponse response = queryTranslog(translogUrl, req.zipCode, weightGrams, service);
148	            if (response == null) {
149	                return new ValidationError("CARRIER_UNAVAILABLE", 503);
150	            }
151	            if (response.error != null && response.error.equals("ZIP_NOT_SERVED")) {
152	                return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
153	            }
154	        }
155	
156	        return null;
157	    }
