159	    private static ValidationError validateCouponApplicability(CheckoutRequest req) throws SQLException {
160	        if (req.coupon == null || req.coupon.isEmpty()) {
161	            return null;
162	        }
163	
164	        double subtotal = 0;
165	        for (CheckoutRequest.OrderItemData item : req.items) {
166	            Product product = ProductService.getProduct(item.sku);
167	            subtotal += product.price * item.quantity;
168	        }
169	        subtotal = MoneyUtils.round(subtotal);
170	
171	        if (req.coupon.equals("WELCOME10")) {
172	            boolean isFirstPurchase = !hasCompletedOrder(req.customer.cpf);
173	            if (!isFirstPurchase) {
174	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
175	            }
176	        } else if (req.coupon.equals("MINUS50")) {
177	            if (subtotal < 300) {
178	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
179	            }
180	        } else if (req.coupon.equals("FREESHIPPING")) {
181	            if (req.shippingMethod.equals("STORE_PICKUP")) {
182	                return new ValidationError("COUPON_NOT_APPLICABLE", 422);
183	            }
184	        }
185	
186	        return null;
187	    }
