199	    public static OrderSummary calculateSummary(CheckoutRequest req) throws SQLException {
200	        double subtotal = 0;
201	        for (CheckoutRequest.OrderItemData item : req.items) {
202	            Product product = ProductService.getProduct(item.sku);
203	            subtotal += product.price * item.quantity;
204	        }
205	        subtotal = MoneyUtils.round(subtotal);
206	
207	        double couponDiscount = 0;
208	        if (req.coupon != null && !req.coupon.isEmpty()) {
209	            couponDiscount = calculateCouponDiscount(req, subtotal);
210	            double maxDiscount = MoneyUtils.round(subtotal * MAX_DISCOUNT_PERCENTAGE);
211	            if (couponDiscount > maxDiscount) {
212	                couponDiscount = maxDiscount;
213	            }
214	        }
215	
216	        double shippingCost = 0;
217	        int deliveryDays = 0;
218	        ShippingInfo shippingInfo = calculateShipping(req);
219	        if (shippingInfo != null) {
220	            shippingCost = shippingInfo.cost;
221	            deliveryDays = shippingInfo.days;
222	        }
223	
224	        if (Enums.ClubTier.valueOf(req.clubTier) == Enums.ClubTier.GOLD &&
225	            !req.shippingMethod.equals("COURIER") &&
226	            !req.shippingMethod.equals("STORE_PICKUP")) {
227	            shippingCost = 0;
228	        }
229	
230	        double insurance = calculateInsurance(req, subtotal);
231	
232	        double totalBeforePayment = subtotal - couponDiscount + shippingCost + insurance;
233	        totalBeforePayment = MoneyUtils.round(totalBeforePayment);
234	
235	        double paymentAdjustment = 0;
236	        int installments = req.installments != null ? req.installments : 1;
237	        double finalTotal = totalBeforePayment;
238	
239	        if (req.coupon == null || req.coupon.isEmpty()) {
240	            if (req.paymentMethod.equals("PIX")) {
241	                double pixDiscount = MoneyUtils.round(totalBeforePayment * 0.05);
242	                paymentAdjustment = -pixDiscount;
243	                finalTotal = MoneyUtils.round(totalBeforePayment - pixDiscount);
244	            } else if (req.paymentMethod.equals("BANK_SLIP")) {
245	                paymentAdjustment = 3.49;
246	                finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
247	            }
248	        } else if (req.paymentMethod.equals("BANK_SLIP")) {
249	            paymentAdjustment = 3.49;
250	            finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
251	        }
252	
253	        double installmentAmount = finalTotal;
254	        if (req.paymentMethod.equals("CREDIT_CARD") && installments > 3) {
255	            double monthlyRate = 0.0199;
256	            double factor = Math.pow(1 + monthlyRate, -installments);
257	            installmentAmount = MoneyUtils.round(finalTotal * monthlyRate / (1 - factor));
258	            finalTotal = MoneyUtils.round(installmentAmount * installments);
259	        } else if (installments > 1) {
260	            installmentAmount = MoneyUtils.round(finalTotal / installments);
261	            finalTotal = MoneyUtils.round(installmentAmount * installments);
262	        }
263	
264	        double credit = 0;
265	        Enums.ClubTier tier = Enums.ClubTier.valueOf(req.clubTier);
266	        if (tier == Enums.ClubTier.SILVER) {
267	            credit = MoneyUtils.round(subtotal * 0.02);
268	        } else if (tier == Enums.ClubTier.GOLD) {
269	            credit = MoneyUtils.round(subtotal * 0.05);
270	        }
271	
272	        boolean gift = tier == Enums.ClubTier.GOLD && subtotal > 500;
273	
274	        return new OrderSummary(
275	            subtotal, couponDiscount, shippingCost, deliveryDays, insurance,
276	            paymentAdjustment, finalTotal, installments, installmentAmount,
277	            credit, gift
278	        );
279	    }
280	
281	    private static double calculateCouponDiscount(CheckoutRequest req, double subtotal) throws SQLException {
282	        String coupon = req.coupon;
283	
284	        if (coupon.equals("WELCOME10")) {
285	            boolean isFirstPurchase = !hasCompletedOrder(req.customer.cpf);
286	            if (!isFirstPurchase) {
287	                return 0;
288	            }
289	            return MoneyUtils.round(subtotal * 0.10);
290	        }
291	
292	        if (coupon.equals("MINUS50")) {
293	            if (subtotal < 300) {
294	                return 0;
295	            }
296	            return 50.0;
297	        }
298	
299	        if (coupon.equals("FREESHIPPING")) {
300	            if (req.shippingMethod.equals("STORE_PICKUP")) {
301	                return 0;
302	            }
303	            ShippingInfo shipping = calculateShipping(req);
304	            if (shipping == null) {
305	                return 0;
306	            }
307	            return shipping.cost;
308	        }
309	
310	        if (coupon.equals("BUY3PAY2")) {
311	            double discount = 0;
312	            for (CheckoutRequest.OrderItemData item : req.items) {
313	                Product product = ProductService.getProduct(item.sku);
314	                int freeUnits = item.quantity / 3;
315	                discount += product.price * freeUnits;
316	            }
317	            return MoneyUtils.round(discount);
318	        }
319	
320	        return 0;
321	    }
322	
323	    private static boolean hasCompletedOrder(String cpf) throws SQLException {
324	        String sql = "SELECT COUNT(*) as count FROM orders WHERE cpf = ? AND (status = 'PAID' OR status = 'SHIPPED' OR status = 'DELIVERED')";
325	        java.sql.Connection conn = Database.getDataSource().getConnection();
326	        java.sql.PreparedStatement pstmt = conn.prepareStatement(sql);
327	        pstmt.setString(1, cpf);
328	        java.sql.ResultSet rs = pstmt.executeQuery();
329	        rs.next();
330	        int count = rs.getInt("count");
331	        rs.close();
332	        pstmt.close();
333	        conn.close();
334	        return count > 0;
335	    }
336	
337	    private static ShippingInfo calculateShipping(CheckoutRequest req) throws SQLException {
338	        Enums.ShippingMethod method = Enums.ShippingMethod.valueOf(req.shippingMethod);
339	
340	        double totalWeight = 0;
341	        for (CheckoutRequest.OrderItemData item : req.items) {
342	            Product product = ProductService.getProduct(item.sku);
343	            totalWeight += product.weightKg * item.quantity;
344	        }
345	
346	        if (method == Enums.ShippingMethod.STORE_PICKUP) {
347	            return new ShippingInfo(0, 1);
348	        }
349	
350	        if (method == Enums.ShippingMethod.COURIER) {
351	            if (totalWeight > MAX_COURIER_WEIGHT) {
352	                return null;
353	            }
354	            return new ShippingInfo(18.0, 0);
355	        }
356	
357	        String translogUrl = System.getenv("TRANSLOG_URL");
358	        if (translogUrl == null || translogUrl.isEmpty()) {
359	            return null;
360	        }
361	
362	        String service = method == Enums.ShippingMethod.ECONOMY ? "STD" : "EXP";
363	        int weightGrams = (int) (totalWeight * 1000);
364	
365	        TranslogResponse response = queryTranslog(translogUrl, req.zipCode, weightGrams, service);
366	        if (response == null) {
367	            return null;
368	        }
369	
370	        if (response.error != null) {
371	            return null;
372	        }
373	
374	        double costReais = response.priceCents / 100.0;
375	        int daysBase = (int) Math.ceil(response.etaHours / 24.0);
376	
377	        Enums.Region region = Enums.Region.valueOf(req.region);
378	        int daysExtra = 0;
379	        if (region == Enums.Region.NORTH) {
380	            daysExtra = 3;
381	        } else if (region == Enums.Region.NORTHEAST) {
382	            daysExtra = 2;
383	        }
384	
385	        return new ShippingInfo(costReais, daysBase + daysExtra);
386	    }
387	
388	    private static TranslogResponse queryTranslog(String baseUrl, String zipCode, int weightGrams, String service) {
389	        try {
390	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", baseUrl, zipCode, weightGrams, service);
391	            java.net.HttpURLConnection conn = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
392	            conn.setRequestMethod("GET");
393	            conn.setConnectTimeout(2000);
394	            conn.setReadTimeout(2000);
395	
396	            int status = conn.getResponseCode();
397	            if (status != 200) {
398	                return null;
399	            }
400	
401	            String response = new String(conn.getInputStream().readAllBytes());
402	            com.google.gson.JsonElement element = com.google.gson.JsonParser.parseString(response);
403	            com.google.gson.JsonObject obj = element.getAsJsonObject();
404	
405	            if (obj.has("error")) {
406	                TranslogResponse resp = new TranslogResponse();
407	                resp.error = obj.get("error").getAsString();
408	                return resp;
409	            }
410	
411	            TranslogResponse resp = new TranslogResponse();
412	            resp.priceCents = obj.get("price_cents").getAsInt();
413	            resp.etaHours = obj.get("eta_hours").getAsInt();
414	            return resp;
415	        } catch (Exception e) {
416	            return null;
417	        }
418	    }
419	
420	    private static double calculateInsurance(CheckoutRequest req, double subtotal) {
421	        Enums.Region region = Enums.Region.valueOf(req.region);
422	        double percentage = 0;
423	        double limit = Double.MAX_VALUE;
424	
425	        switch (region) {
426	            case SOUTHEAST, SOUTH -> percentage = 0.01;
427	            case MIDWEST -> percentage = 0.015;
428	            case NORTH -> {
429	                percentage = 0.025;
430	                limit = 30.0;
431	            }
432	            case NORTHEAST -> {
433	                percentage = 0.02;
434	                limit = 30.0;
435	            }
436	        }
437	
438	        double insurance = MoneyUtils.round(subtotal * percentage);
439	        if (insurance > limit) {
440	            insurance = limit;
441	        }
442	        return insurance;
443	    }
444	
445	    private static boolean isInstallmentsValid(String paymentMethod, int installments) {
446	        if (installments < 1 || installments > 12) {
447	            return false;
448	        }
449	        if (paymentMethod.equals("PIX") || paymentMethod.equals("BANK_SLIP")) {
450	            return installments == 1;
451	        }
452	        return true;
453	    }
454	
455	    private static boolean isCouponValid(String coupon) {
456	        return coupon.equals("WELCOME10") || coupon.equals("MINUS50") ||
457	               coupon.equals("FREESHIPPING") || coupon.equals("BUY3PAY2");
458	    }
