199	    public static OrderSummary calculateSummary(CheckoutRequest req) throws SQLException {
200	        double subtotal = 0;
201	        for (CheckoutRequest.OrderItemData item : req.items) {
202	            Product product = ProductService.getProduct(item.sku);
203	            subtotal += product.price * item.quantity;
204	        }
205	        subtotal = MoneyUtils.round(subtotal);
206	
207	        double couponDiscount = 0;
208	        if (req.coupon != null && !req.coupon.isEmpty()) {
209	            couponDiscount = calculateCouponDiscount(req, subtotal);
210	            double maxDiscount = MoneyUtils.round(subtotal * MAX_DISCOUNT_PERCENTAGE);
211	            if (couponDiscount > maxDiscount) {
212	                couponDiscount = maxDiscount;
213	            }
214	        }
215	
216	        double shippingCost = 0;
217	        int deliveryDays = 0;
218	        ShippingInfo shippingInfo = calculateShipping(req);
219	        if (shippingInfo != null) {
220	            shippingCost = shippingInfo.cost;
221	            deliveryDays = shippingInfo.days;
222	        }
223	
224	        if (Enums.ClubTier.valueOf(req.clubTier) == Enums.ClubTier.GOLD &&
225	            !req.shippingMethod.equals("COURIER") &&
226	            !req.shippingMethod.equals("STORE_PICKUP")) {
227	            shippingCost = 0;
228	        }
229	
230	        double insurance = calculateInsurance(req, subtotal);
231	
232	        double totalBeforePayment = subtotal - couponDiscount + shippingCost + insurance;
233	        totalBeforePayment = MoneyUtils.round(totalBeforePayment);
234	
235	        double paymentAdjustment = 0;
236	        int installments = req.installments != null ? req.installments : 1;
237	        double finalTotal = totalBeforePayment;
238	
239	        if (req.coupon == null || req.coupon.isEmpty()) {
240	            if (req.paymentMethod.equals("PIX")) {
241	                double pixDiscount = MoneyUtils.round(totalBeforePayment * 0.05);
242	                paymentAdjustment = -pixDiscount;
243	                finalTotal = MoneyUtils.round(totalBeforePayment - pixDiscount);
244	            } else if (req.paymentMethod.equals("BANK_SLIP")) {
245	                paymentAdjustment = 3.49;
246	                finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
247	            }
248	        } else if (req.paymentMethod.equals("BANK_SLIP")) {
249	            paymentAdjustment = 3.49;
250	            finalTotal = MoneyUtils.round(totalBeforePayment + 3.49);
251	        }
252	
253	        double installmentAmount = finalTotal;
254	        if (req.paymentMethod.equals("CREDIT_CARD") && installments > 3) {
255	            double monthlyRate = 0.0199;
256	            double factor = Math.pow(1 + monthlyRate, -installments);
257	            installmentAmount = MoneyUtils.round(finalTotal * monthlyRate / (1 - factor));
258	            finalTotal = MoneyUtils.round(installmentAmount * installments);
259	        } else if (installments > 1) {
260	            installmentAmount = MoneyUtils.round(finalTotal / installments);
261	            finalTotal = MoneyUtils.round(installmentAmount * installments);
262	        }
263	
264	        double credit = 0;
265	        Enums.ClubTier tier = Enums.ClubTier.valueOf(req.clubTier);
266	        if (tier == Enums.ClubTier.SILVER) {
267	            credit = MoneyUtils.round(subtotal * 0.02);
268	        } else if (tier == Enums.ClubTier.GOLD) {
269	            credit = MoneyUtils.round(subtotal * 0.05);
270	        }
271	
272	        boolean gift = tier == Enums.ClubTier.GOLD && subtotal > 500;
273	
274	        return new OrderSummary(
275	            subtotal, couponDiscount, shippingCost, deliveryDays, insurance,
276	            paymentAdjustment, finalTotal, installments, installmentAmount,
277	            credit, gift
278	        );
279	    }
